import React from 'react';
import './App.css';

/**
 * ?  =====Import Components=====
 */
import Home from './Pages/Home';
import Signup from './Pages/Signup'
import { BrowserRouter as Router ,Route} from 'react-router-dom';

function App() {
  return (
    <div>
      <Router>
        <Route exa path='/' element={ <Home /> } />
        <Route path='/signup' element={<Signup/>} />
      </Router>
      
    </div>
  );
}

export default App;
